import { useEffect, useRef } from "react";
import { v4 as uuid } from "uuid";
import { INSPECTOR_CHANNEL_NAME } from "../constants";
import { useBotConnection } from "../hooks/useBotConnection";
import { useTrackerConnection } from "../hooks/useTrackerConnection";
import { setInspectMode } from "../store/actions";
import { initInspectorStore, inspectorStore, type InspectorStoreState } from "../store";
import { TryAssistant } from "../try-assistant/TryAssistant";
import type { InspectorProps } from "./Inspector";

type InspectorContentProps = Omit<
  InspectorProps,
  "track" | "logError" | "showToast" | "onboardingTooltips" | "socketReconnectAttempts"
> & { isEmbedded: boolean };

export const InspectorContent = (props: InspectorContentProps) => {
  const {
    projectUrl,
    singleSessionMode,
    projectId,
    sessionId,
    resetSession,
    onSessionStart,
    onReconnectError,
    onMessageSent,
    channel,
  } = props;

  const initialized = useRef<boolean>(null);
  if (initialized.current === null) {
    initialized.current = true;
    initInspectorStore({
      projectUrl,
      botDataEndpoint: props.botDataEndpoint,
      httpAuth: props.httpAuth,
      socketEndpoint: props.socketEndpoint,
      socketAuth: props.socketAuth,
      trackerEndpoint: props.trackerEndpoint,
      conversationEventActions: props.conversationEventActions ?? [],
      voiceFeaturesEnabled: props.voiceFeaturesEnabled ?? true,
      inspectMode: props.inspectMode ?? props.initialInspectMode ?? false,
      isEmbedded: props.isEmbedded,
    });
  }

  const isTrackerMode = !!channel && channel !== INSPECTOR_CHANNEL_NAME;

  useBotConnection({
    projectId: projectId ?? uuid(),
    useMemoryOnly: singleSessionMode ?? false,
    sessionId,
    resetSession,
    onSessionStart,
    onReconnectError,
    onMessageSent,
    enabled: !isTrackerMode,
  });

  useTrackerConnection({ enabled: isTrackerMode, channel: channel ?? "" });

  useEffect(() => {
    if (props.inspectMode !== undefined) {
      setInspectMode(props.inspectMode);
    }
  }, [props.inspectMode]);

  // Serialize socketAuth so inline object literals from the host do not retrigger
  // this effect (and socket reconnects) on every parent render.
  const socketAuthKey = JSON.stringify(props.socketAuth ?? null);

  useEffect(() => {
    const updates: Partial<InspectorStoreState> = {};

    if (projectUrl) updates.projectUrl = projectUrl;
    if (props.botDataEndpoint) updates.botDataEndpoint = props.botDataEndpoint;
    if (props.trackerEndpoint) updates.trackerEndpoint = props.trackerEndpoint;
    updates.httpAuth = props.httpAuth;
    updates.socketEndpoint = props.socketEndpoint;
    updates.socketAuth = props.socketAuth;
    if (props.conversationEventActions)
      updates.conversationEventActions = props.conversationEventActions;
    if (typeof props.voiceFeaturesEnabled === "boolean")
      updates.voiceFeaturesEnabled = props.voiceFeaturesEnabled;

    if (Object.keys(updates).length > 0) {
      inspectorStore.setState((prev) => ({ ...prev, ...updates }));
    }
    // props.socketAuth is read inside but keyed by socketAuthKey for stable identity.
    // eslint-disable-next-line react-hooks/exhaustive-deps -- socketAuthKey stands in for props.socketAuth
  }, [
    projectUrl,
    props.botDataEndpoint,
    props.trackerEndpoint,
    props.httpAuth?.token,
    props.httpAuth?.via,
    props.socketEndpoint,
    socketAuthKey,
    props.conversationEventActions,
    props.voiceFeaturesEnabled,
  ]);

  return <TryAssistant onInspectModeChange={props.onInspectModeChange} />;
};
